<script setup>
import { computed, ref, watch } from 'vue'
import { Archive, ArrowLeft, BookOpenText, ChevronLeft, ChevronRight, Eye, FilePlus2, Filter, Info, Pencil, Plus, Search, ShieldCheck, ToggleLeft, ToggleRight, Trash2 } from 'lucide-vue-next'
import ModalShell from './ModalShell.vue'
import QuestionChart from './QuestionChart.vue'
import QuestionEditorForm from './QuestionEditorForm.vue'
import { friendlyDate, previewText } from '../data/questionManagement.js'

const props = defineProps({ questions: { type: Array, required: true }, suggestions: { type: Array, required: true }, history: { type: Array, default: () => [] } })
const emit = defineEmits(['save-question', 'archive', 'change-status', 'open-review'])
const filterTask = ref('all'); const filterStatus = ref('all'); const filterTopic = ref('all'); const search = ref(''); const index = ref(0)
const view = ref('list') // list | add | edit | details
const selectedId = ref(null)
const archiveTarget = ref(null)
const alert = ref('')
const selected = computed(() => props.questions.find(q => q.id === selectedId.value) || null)
const topics = computed(() => [...new Set(props.questions.map(q => q.topic).filter(Boolean))].sort())
const filtered = computed(() => props.questions.filter(q => (filterTask.value === 'all' || String(q.task) === filterTask.value) && (filterStatus.value === 'all' || q.status === filterStatus.value) && (filterTopic.value === 'all' || q.topic === filterTopic.value) && (!search.value.trim() || `${q.question} ${q.topic} ${q.source} ${q.id}`.toLowerCase().includes(search.value.toLowerCase().trim()))).sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt)))
const pageSize = 6
const pageCount = computed(() => Math.max(1, Math.ceil(filtered.value.length / pageSize)))
const visible = computed(() => filtered.value.slice(index.value * pageSize, (index.value + 1) * pageSize))
watch([filterTask,filterStatus,filterTopic,search], ()=>{index.value=0})
watch(pageCount, total => { if (index.value >= total) index.value = total - 1 })
const pendingCount = computed(() => props.suggestions.filter(s => s.status === 'pending').length)
const linkedCount = computed(() => archiveTarget.value ? props.history.filter(item => item.questionId === archiveTarget.value.id || item.question === archiveTarget.value.question).length : 0)
function save(value) { emit('save-question', { ...value, id: view.value === 'edit' ? selectedId.value : undefined }); view.value = 'list'; alert.value = 'Question saved to the local demo bank.' }
function showEdit(id) { selectedId.value = id; view.value = 'edit'; window.scrollTo({top:0,behavior:'smooth'}) }
function showDetail(id) { selectedId.value = id; view.value = 'details'; window.scrollTo({top:0,behavior:'smooth'}) }
function changeStatus(item) { if (item.status === 'archived') return; if (item.task === 1 && !item.visual && item.status !== 'active') { alert.value = 'Add a Task 1 visual before publishing this question.'; return } emit('change-status', { id: item.id, status: item.status === 'active' ? 'draft' : 'active' }); alert.value = 'Publication status changed.' }
function archiveConfirmed() { if (!archiveTarget.value) return; emit('archive', archiveTarget.value.id); archiveTarget.value = null; alert.value='Question archived. Historical essay submissions remain unchanged.' }
</script>
<template>
  <section class="page-header"><div><p class="eyebrow">ADMIN / QUESTION BANK</p><h1>{{ view === 'add' ? 'Add New Question' : view === 'edit' ? 'Edit Question' : view === 'details' ? 'Question Details' : 'Question Management' }}</h1><p class="page-subtitle">{{ view === 'list' ? 'Manage standardized writing questions, publication status, and learner suggestions.' : 'Question content and publication details.' }}</p></div><button v-if="view==='list'" class="btn btn-primary" @click="view='add'; selectedId=null"><Plus :size="17"/>Add question</button><button v-else class="btn btn-outline" @click="view='list'"><ArrowLeft :size="16"/>Back to bank</button></section>
  <div class="qm-page">
    <div v-if="alert" class="qm-inline-notice" role="status"><Info :size="17"/><span>{{ alert }}</span><button @click="alert=''">Dismiss</button></div>
    <template v-if="view==='list'">
      <section class="qm-panel qm-list-panel">
        <div class="qm-bank-bar"><div class="qm-tab-strip" role="group" aria-label="Task filter"><button v-for="value in [{key:'all',label:'All questions'}, {key:'1',label:'Task 1'},{key:'2',label:'Task 2'}]" :key="value.key" :class="{ active:filterTask===value.key }" @click="filterTask=value.key">{{ value.label }}</button></div><button class="btn btn-outline" @click="emit('open-review')"><ShieldCheck :size="16"/>Review suggestions <span v-if="pendingCount" class="qm-count-pill">{{pendingCount}}</span></button></div>
        <div class="qm-filter-bar"><label class="qm-search"><Search :size="17"/><input v-model="search" placeholder="Search questions, topics, IDs…" aria-label="Search question bank"/></label><select v-model="filterTopic" class="qm-control qm-filter-select" aria-label="Filter by topic"><option value="all">All topics</option><option v-for="topic in topics" :key="topic">{{ topic }}</option></select><select v-model="filterStatus" class="qm-control qm-filter-select" aria-label="Filter by status"><option value="all">All statuses</option><option value="active">Active</option><option value="draft">Draft</option><option value="archived">Archived</option></select></div>
        <div class="qm-table-scroll"><table class="qm-table"><thead><tr><th>ID</th><th>Question preview</th><th>Task</th><th>Topic</th><th>Status</th><th>Added</th><th class="qm-table-right">Actions</th></tr></thead><tbody><tr v-for="q in visible" :key="q.id"><td><strong class="qm-id">{{ q.id.length>15 ? q.id.slice(0,12)+'…' : q.id }}</strong></td><td><button class="qm-question-preview" @click="showDetail(q.id)"><span v-if="q.visual" class="qm-small-visual"><img v-if="q.visual.startsWith('data:')" :src="q.visual" alt="Question visual thumbnail"/><BookOpenText v-else :size="17"/></span><span>{{previewText(q.question,92)}}</span></button></td><td><span class="qm-task-pill">Task {{q.task}}</span></td><td>{{q.topic}}</td><td><span class="qm-status" :class="`qm-status-${q.status}`">{{q.status}}</span></td><td class="qm-nowrap">{{friendlyDate(q.createdAt)}}</td><td><div class="qm-row-actions"><button class="qm-square" title="View details" :aria-label="`View ${q.id}`" @click="showDetail(q.id)"><Eye :size="16"/></button><button class="qm-square" title="Edit question" :aria-label="`Edit ${q.id}`" @click="showEdit(q.id)"><Pencil :size="16"/></button><button class="qm-square qm-danger" :disabled="q.status==='archived'" title="Archive question" :aria-label="`Archive ${q.id}`" @click="archiveTarget=q"><Archive :size="16"/></button></div></td></tr><tr v-if="!visible.length"><td colspan="7" class="qm-table-empty">No questions match these filters.</td></tr></tbody></table></div>
        <div class="qm-table-footer"><span>Showing {{ filtered.length ? index*pageSize+1 : 0 }}–{{Math.min((index+1)*pageSize,filtered.length)}} of {{filtered.length}} questions</span><div class="qm-pagination"><button :disabled="index===0" @click="index--" aria-label="Previous page"><ChevronLeft :size="17"/></button><span>Page {{index+1}} of {{pageCount}}</span><button :disabled="index>=pageCount-1" @click="index++" aria-label="Next page"><ChevronRight :size="17"/></button></div></div>
      </section>
      <div class="qm-demo-note"><Info :size="16"/>Archive removes questions from new assignments; previously saved essay question text is preserved. All changes are local demo data.</div>
    </template>
    <QuestionEditorForm v-else-if="view==='add' || (view==='edit'&&selected)" :mode="view" :initial="view==='edit'?selected:null" :known-questions="questions" @save="save" @cancel="view='list'"/>
    <section v-else-if="view==='details' && selected" class="qm-panel qm-detail"><div class="qm-panel-title"><div><h2>Question {{selected.id}}</h2><p>Added {{friendlyDate(selected.createdAt)}} · {{selected.source || 'No source given'}}</p></div><span class="qm-status" :class="`qm-status-${selected.status}`">{{selected.status}}</span></div><div class="qm-detail-cols"><div><div class="qm-detail-essay"><span>QUESTION TEXT</span><p>{{selected.question}}</p></div><div v-if="selected.visual" class="qm-detail-image"><strong>Associated Task 1 visual</strong><img v-if="selected.visual.startsWith('data:')" :src="selected.visual" alt="Task 1 question visual"/><QuestionChart v-else :variant="selected.visual"/></div><p v-if="selected.visualNotes" class="qm-visual-note">Visual notes: {{selected.visualNotes}}</p></div><dl class="qm-info-grid"><div><dt>Task type</dt><dd>Task {{selected.task}}</dd></div><div><dt>Topic</dt><dd>{{selected.topic}}</dd></div><div><dt>Source</dt><dd>{{selected.source||'Not specified'}}</dd></div><div><dt>Publication</dt><dd class="qm-uppercase">{{selected.status}}</dd></div><div><dt>Last updated</dt><dd>{{friendlyDate(selected.updatedAt)}}</dd></div><div><dt>Suggestion origin</dt><dd>{{selected.suggestionId?'Learner suggestion':'Added to bank'}}</dd></div></dl></div><div class="qm-form-footer"><button class="btn btn-outline" @click="view='list'">Back to bank</button><button v-if="selected.status!=='archived'" class="btn btn-outline" @click="changeStatus(selected)">{{selected.status==='active'?'Move to Draft':'Publish question'}}</button><button class="btn btn-primary" @click="showEdit(selected.id)"><Pencil :size="16"/>Edit question</button></div></section>
  </div>
  <ModalShell v-if="archiveTarget" title="Archive this question?" @close="archiveTarget=null"><div class="qm-dialog-description"><Archive :size="23"/><div><strong>Question {{archiveTarget.id}}</strong><p>{{previewText(archiveTarget.question,180)}}</p></div></div><p class="qm-dialog-copy">Archiving will prevent this question from being assigned in future mock tests or practice sessions. {{linkedCount ? `${linkedCount} historical demo submission(s) reference this question; their text will be retained.` : 'Any historical submissions remain intact.'}} This is not permanent deletion.</p><template #footer><button class="btn btn-outline" @click="archiveTarget=null">Cancel</button><button class="btn btn-primary" @click="archiveConfirmed"><Archive :size="16"/>Archive question</button></template></ModalShell>
</template>
